// webhook data under "$json.body").
// ---------------------------------------------------------------
const raw    = $json || {};                     // root: fields added by Config Set
const src    = raw.body || raw;                // payload: either $json.body or the whole object
const values = src.values ?? src.body?.values ?? {}; // try src.values, then src.body.values, else {}

