const cfg = {
  defaultDryRun:   !!raw.defaultDryRun,
  authHeaderName:  String(raw.authHeaderName || 'x-lt-webhook-key').toLowerCase(),
  authHeaderValue: String(raw.authHeaderValue || ''), // empty → auth disabled
  provider:        String(raw.provider || 'SimpleTexting').trim(),
  eventType:       String(raw.eventType || 'inbound_reply').trim(),
  ghlLocationId:   String(raw.ghlLocationId || '').trim(),
  ghlApiBaseUrl:   String(raw.ghlApiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, ''),
  ghlApiKey:       String(raw.ghlApiKey || '').trim(),
  tagOngoing:      String(raw.tagOngoing || 'simpletext_ongoing').trim(),
  tagStop:         String(raw.tagStop || 'simpletext_stop').trim(),
  tagReply:        String(raw.tagReply || 'simpletext_replied').trim(),
};
// ---------- Helper utilities ----------
function clean(v) { return String(v ?? '').trim(); }
function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).toLowerCase();
  if (['true','1','yes','y'].includes(s)) return true;
  if (['false','0','no','n'].includes(s)) return false;
  return fallback;
}
function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}
function formatPhone(v) {
  const d = normalizePhone(v);
  if (!d) return '';
  if (d.length === 10) return `+1 ${d.slice(0,3)}-${d.slice(3,6)}-${d.slice(6)}`;
  return `+${d}`;
}
function normalizeMediaItems(src) {
  const items = [];
  if (Array.isArray(src.mediaItems)) items.push(...src.mediaItems);
  if (Array.isArray(src.mediaUrls))  items.push(...src.mediaUrls);
  if (src.mediaUrl) items.push(src.mediaUrl);
  return items.map(i => clean(i)).filter(Boolean);
}
function formatSlackSummary(d) {
  const lines = [];
  lines.push('*Inbound SimpleTexting Reply*');
  lines.push(`*From:* ${d.fromPretty || d.from || 'Unknown'}`);
  if (d.contactName) lines.push(`*Contact Name:* ${d.contactName}`);
  if (d.contactId)   lines.push(`*GHL Contact ID:* ${d.contactId}`);
  if (d.resolvedVia) lines.push(`*Matched Via:* ${d.resolvedVia}`);
  if (d.receivedAt)  lines.push(`*Received At:* ${d.receivedAt}`);
  if (d.subject)     lines.push(`*Subject:* ${d.subject}`);
  if (d.providerMessageId) lines.push(`*Provider Message ID:* ${d.providerMessageId}`);
  if (d.unsubscribeKeyword) lines.push('*Status:* STOP keyword detected');
  lines.push('');
  lines.push('*Message:*');
  lines.push(d.message || '[media only reply]');
  if (d.mediaItems?.length) {
    lines.push('');
    lines.push('*Media:*');
    d.mediaItems.forEach(i => lines.push(i));
  }
