const from = normalizePhone(
  values.contactPhone ||
  src.contactPhone ||
  src.from ||
  src.phone ||
  src.mobile ||
  src.senderPhone
);
const to = normalizePhone(
  values.accountPhone ||
  src.accountPhone ||
  src.to ||
  src.destination ||
  src.number
);
