    attempted: true,
    ok: noteRes.ok,
    contactId: resolvedContact.contactId,
    resolvedVia: resolvedContact.resolvedVia,
    details: noteRes.ok ? (noteRes.data?.note || noteRes.data) : noteRes.data,
  };
