    const addRes = await addTags.call(this, resolvedContact.contactId, [cfg.tagStop]);
    const removeRes = await removeTags.call(this, resolvedContact.contactId, [cfg.tagOngoing]);
    tagSync = {
      attempted: true,
      contactId: resolvedContact.contactId,
      added: [cfg.tagStop],
      removed: [cfg.tagOngoing],
      addOk: !!addRes.ok,
      removeOk: !!removeRes.ok,
      addDetails: addRes.ok ? (addRes.data?.contact || addRes.data) : addRes.data,
      removeDetails: removeRes.ok ? (removeRes.data?.contact || removeRes.data) : removeRes.data,
    };
  } else {
    const addRes = await addTags.call(this, resolvedContact.contactId, [cfg.tagReply]);
    const removeRes = await removeTags.call(this, resolvedContact.contactId, [cfg.tagOngoing]);
    tagSync = {
      attempted: true,
      contactId: resolvedContact.contactId,
      added: [cfg.tagReply],
      removed: [cfg.tagOngoing],
      addOk: !!addRes.ok,
      removeOk: !!removeRes.ok,
      addDetails: addRes.ok ? (addRes.data?.contact || addRes.data) : addRes.data,
      removeDetails: removeRes.ok ? (removeRes.data?.contact || removeRes.data) : removeRes.data,
    };
  }
}
// ------- Final output -------
return [{ json: {
  ok: true,
  dryRun,
  provider: cfg.provider,
  eventType: cfg.eventType,
  reportType,
  from,
  fromPretty,
  contactName: resolvedContact.contactName || '',
  contactId: resolvedContact.contactId || '',
  message,
  subject,
  mediaItems,
  providerMessageId,
  providerContactId,
  receivedAt,
  category,
  referenceType,
  unsubscribeKeyword,
  ghlNoteSync: noteSync,
  ghlTagSync: tagSync,
  slackMessage: formatSlackSummary({
    fromPretty,
    contactName: resolvedContact.contactName || '',
    contactId: resolvedContact.contactId || '',
    resolvedVia: resolvedContact.resolvedVia || '',
    receivedAt,
    subject,
    providerMessageId,
    unsubscribeKeyword,
    message,
    mediaItems,
  }),
  rawBody: src,
  rawValues: values,
  nextStep: unsubscribeKeyword
    ? 'reply_logged_and_contact_stopped'
    : (noteSync.ok ? 'reply_logged_to_ghl' : 'reply_logged_pending_manual_review'),
} }];

