const to = normalizePhone(
  values.accountPhone ||
  src.accountPhone ||
  src.to ||
  src.destination ||
  src.number
);
// ------- MESSAGE & MEDIA -------
const message    = clean(values.text || src.text || src.message || src.body || src.smsBody);
const subject    = clean(values.subject || src.subject);
const mediaItems = normalizeMediaItems(values).length ? normalizeMediaItems(values) : normalizeMediaItems(src);
// ------- IDS & TIMESTAMPS -------
const providerMessageId = clean(values.messageId || src.messageId || src.message_id || src.id || src.smid);
const providerContactId = clean(values.contactId || src.contactId);
const receivedAt        = clean(values.timestamp || src.receivedAt || src.timestamp || src.createdAt || src.date || new Date().toISOString());
// ------- MISC -------
const category       = clean(values.category || src.category);
const referenceType  = clean(values.referenceType || src.referenceType);
const normalizedKeyword = message.toLowerCase().replace(/[^a-z]/g, '');
const unsubscribeKeyword = ['stop','stopall','unsubscribe','cancel','end','quit'].includes(normalizedKeyword);
// ------- Guard clauses -------
if (!from)  return [{ json: { ok: false, error: 'missing_from_phone',  message: 'Provide values.contactPhone or a fallback from/phone field' } }];
if (!message && mediaItems.length === 0) return [{ json: { ok: false, error: 'missing_message', message: 'Provide values.text or mediaItems' } }];
// ------- GHL contact resolution -------
const resolvedContact = await resolveGhlContact.call(this, from, explicitGhlContactId);
const fromPretty = formatPhone(from) || from;
// ------- Build GHL note body -------
const noteBody = [
  unsubscribeKeyword ? 'SMS STOP reply received via SimpleTexting' : 'SMS reply received via SimpleTexting',
  `Received At: ${receivedAt}`,
  `From: ${fromPretty}`,
  to ? `To: ${formatPhone(to) || to}` : '',
  providerMessageId ? `Provider Message ID: ${providerMessageId}` : '',
  providerContactId ? `Provider Contact ID: ${providerContactId}` : '',
  subject ? `Subject: ${subject}` : '',
  category ? `Category: ${category}` : '',
  referenceType ? `Reference Type: ${referenceType}` : '',
  unsubscribeKeyword ? 'Opt-Out: STOP keyword detected' : '',
  'Message:',
  message || '[media only reply]',
  mediaItems.length ? `Media Items: ${mediaItems.join(', ')}` : '',
].filter(Boolean).join('\n');
// ------- Dry‑run response -------
if (dryRun) {
  return [{ json: {
    ok: true,
    dryRun,
    provider: cfg.provider,
    eventType: cfg.eventType,
    reportType,
    from,
    fromPretty,
    contactName: resolvedContact.contactName || '',
    contactId: resolvedContact.contactId || '',
    message,
    subject,
    mediaItems,
    providerMessageId,
    providerContactId,
    receivedAt,
    category,
    referenceType,
    unsubscribeKeyword,
    slackMessage: formatSlackSummary({
      fromPretty,
      contactName: resolvedContact.contactName || '',
      contactId: resolvedContact.contactId || '',
      resolvedVia: resolvedContact.resolvedVia || '',
      receivedAt,
      subject,
      providerMessageId,
      unsubscribeKeyword,
      message,
      mediaItems,
    }),
    ghlNotePreview: noteBody,
    ghlContactResolution: resolvedContact,
    requestedTagAdds: unsubscribeKeyword ? [cfg.tagStop] : [cfg.tagReply],
    requestedTagRemovals: [cfg.tagOngoing].filter(Boolean),
    rawBody: src,
    rawValues: values,
    nextStep: 'draft_only_no_side_effects',
  } }];
}
// ------- GHL sync (note & tags) -------
let noteSync = { attempted: false, contactId: resolvedContact.contactId || '', resolvedVia: resolvedContact.resolvedVia || '', ok: false };
let tagSync  = { attempted: false, contactId: resolvedContact.contactId || '', added: [], removed: [], addOk: false, removeOk: false };
if (cfg.ghlApiKey && cfg.ghlLocationId && resolvedContact.contactId) {
  const noteRes = await createGhlNote.call(this, resolvedContact.contactId, noteBody);
  noteSync = {
    attempted: true,
    ok: noteRes.ok,
    contactId: resolvedContact.contactId,
    resolvedVia: resolvedContact.resolvedVia,
    details: noteRes.ok ? (noteRes.data?.note || noteRes.data) : noteRes.data,
  };
  if (unsubscribeKeyword) {
    const addRes = await addTags.call(this, resolvedContact.contactId, [cfg.tagStop]);
    const removeRes = await removeTags.call(this, resolvedContact.contactId, [cfg.tagOngoing]);
    tagSync = {
      attempted: true,
      contactId: resolvedContact.contactId,
      added: [cfg.tagStop],
      removed: [cfg.tagOngoing],
      addOk: !!addRes.ok,
      removeOk: !!removeRes.ok,
      addDetails: addRes.ok ? (addRes.data?.contact || addRes.data) : addRes.data,
      removeDetails: removeRes.ok ? (removeRes.data?.contact || removeRes.data) : removeRes.data,
    };
  } else {
    const addRes = await addTags.call(this, resolvedContact.contactId, [cfg.tagReply]);
    const removeRes = await removeTags.call(this, resolvedContact.contactId, [cfg.tagOngoing]);
    tagSync = {
      attempted: true,
      contactId: resolvedContact.contactId,
      added: [cfg.tagReply],
      removed: [cfg.tagOngoing],
      addOk: !!addRes.ok,
      removeOk: !!removeRes.ok,
      addDetails: addRes.ok ? (addRes.data?.contact || addRes.data) : addRes.data,
      removeDetails: removeRes.ok ? (removeRes.data?.contact || removeRes.data) : removeRes.data,
    };
  }
}
// ------- Final output -------
return [{ json: {
  ok: true,
  dryRun,
  provider: cfg.provider,
  eventType: cfg.eventType,
  reportType,
  from,
  fromPretty,
  contactName: resolvedContact.contactName || '',
  contactId: resolvedContact.contactId || '',
  message,
  subject,
  mediaItems,
  providerMessageId,
  providerContactId,
  receivedAt,
  category,
  referenceType,
  unsubscribeKeyword,
  ghlNoteSync: noteSync,
  ghlTagSync: tagSync,
  slackMessage: formatSlackSummary({
    fromPretty,
    contactName: resolvedContact.contactName || '',
    contactId: resolvedContact.contactId || '',
    resolvedVia: resolvedContact.resolvedVia || '',
    receivedAt,
    subject,
    providerMessageId,
    unsubscribeKeyword,
    message,
    mediaItems,
  }),
  rawBody: src,
  rawValues: values,
  nextStep: unsubscribeKeyword
    ? 'reply_logged_and_contact_stopped'
    : (noteSync.ok ? 'reply_logged_to_ghl' : 'reply_logged_pending_manual_review'),
} }];
